window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[325]={"id":"325","numero":325,"titre":"Risque médicamenteux, iatrogène","objectifs":[{"id":"325-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un effet indésirable médicamenteux (EIM)","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Un <span class=\"kw-def\">effet indésirable médicamenteux (EIM)</span> est une <span class=\"kw-def\">réaction nocive et non voulue</span> à un médicament, survenant aussi bien lors d'une <span class=\"kw-def\">utilisation conforme à l'AMM</span> que lors de <span class=\"kw-etio\">tout autre usage</span> : <span class=\"kw-etio\">surdosage</span>, <span class=\"kw-etio\">mésusage</span>, <span class=\"kw-etio\">abus</span> ou <span class=\"kw-etio\">erreur médicamenteuse</span>.</div>\n\n      <p><strong>Tout symptôme ou syndrome peut être un EIM</strong> → c'est le <span class=\"kw-def\">réflexe iatrogène</span> à avoir devant chaque patient : « <em>Et si c'était le médicament ?</em> ». À distinguer absolument : un EIM <strong>n'est pas synonyme d'<span class=\"kw-alerte\">erreur médicale</span></strong> ni de « mauvais médicament ».</p>\n\n      <p><strong>Qualificatifs d'un EIM (à connaître) :</strong></p>\n      <ul>\n        <li><strong>Attendu</strong> (<span class=\"kw-def\">labelled</span>) : mentionné dans le <span class=\"kw-bio\">RCP</span> (ex. <span class=\"kw-clinique\">hypotension</span> sous antihypertenseur) — vs <strong>inattendu</strong> (<span class=\"kw-def\">unlabelled</span>), jamais encore rapporté.</li>\n        <li><strong>Évitable</strong> (respect des CI, posologies, surveillance) — vs <strong>inévitable</strong>. <span class=\"kw-chiffre\">Un EIM sur deux</span> est évitable.</li>\n        <li><strong>Grave</strong> (<span class=\"kw-alerte\">EIG</span> : décès, mise en jeu du <span class=\"kw-alerte\">pronostic vital</span>, invalidité, hospitalisation) — vs non grave.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Piège verbatim — gravité ≠ sévérité.</strong> La <span class=\"kw-def\">gravité</span> renvoie aux conséquences (décès, hospitalisation…) ; la <span class=\"kw-def\">sévérité</span> renvoie seulement à l'<span class=\"kw-clinique\">intensité</span> du symptôme.</div>\n\n      <p>La survenue de tout EIM, <strong>quelle qu'en soit la gravité</strong>, impose une <strong>déclaration immédiate au <span class=\"kw-def\">CRPV</span></strong> : c'est une <strong>obligation légale</strong>.</p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":0},{"id":"325-2","rang":"A","rubrique":"Définition","titre":"Comprendre les enjeux concernant les risques liés aux médicaments et aux biomatériaux","contenu":"<p>Les <span class=\"kw-ttt\">médicaments</span> et les <span class=\"kw-ttt\">biomatériaux</span> sont des <span class=\"kw-def\">xénobiotiques</span> (<span class=\"kw-def\">substances étrangères</span> à l'organisme) : leur usage induit <strong>par nature</strong> un risque d'<span class=\"kw-def\">effet indésirable</span>. Maîtriser ce risque est un <strong>enjeu de <span class=\"kw-def\">santé publique</span> majeur</strong>.</p>\n\n      <p><strong>Poids de la iatrogénie médicamenteuse :</strong></p>\n      <ul>\n        <li>Responsable d'environ <span class=\"kw-chiffre\">10 %</span> des <span class=\"kw-clinique\">hospitalisations</span> ; cause majeure de <span class=\"kw-clinique\">morbi-mortalité</span>.</li>\n        <li><span class=\"kw-alerte\">Retentissement économique</span> lourd : <span class=\"kw-clinique\">hospitalisations</span> et prolongations, <span class=\"kw-bio\">examens complémentaires</span> inutiles et coûteux.</li>\n        <li>Le non-diagnostic d'un <span class=\"kw-def\">EIM</span> peut conduire à <strong>prescrire un médicament de plus</strong> (masquant le <span class=\"kw-clinique\">symptôme</span>) → <span class=\"kw-alerte\">cascade médicamenteuse</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Gestion des risques.</strong> Démarche en deux temps : une <span class=\"kw-def\">veille et analyse</span> des risques, puis des actions <strong><span class=\"kw-def\">préventives</span></strong> (supprimer/diminuer les facteurs de risque) et <strong><span class=\"kw-def\">correctives</span></strong> (réduire les conséquences d'un EI avéré). Toute décision s'apprécie par la <span class=\"kw-def\">balance bénéfices-risques</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":0},{"id":"325-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une prescription médicamenteuse inappropriée (PMI)","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Une <span class=\"kw-def\">prescription médicamenteuse inappropriée (PMI)</span> est l'emploi d'un médicament <strong>engendrant plus de risques que de bénéfices</strong> pour le patient.</div>\n\n      <p><strong>Trois dimensions (mémo : over / mis / under) :</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Définition</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Overuse</span> (excès)</td>\n            <td>Médicament <strong>sans indication</strong> ou à <span class=\"kw-bio\">SMR insuffisant</span></td>\n            <td>Maintien d'un médicament devenu inutile ; absence de réévaluation</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Misuse</span> (mésusage)</td>\n            <td>Mauvais <strong>choix</strong>, <span class=\"kw-alerte\">interactions</span> cliniquement significatives, posologie/durée inadaptées</td>\n            <td><span class=\"kw-ci\">Anticholinergique</span> chez un <span class=\"kw-clinique\">sujet âgé confus</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Underuse</span> (sous-prescription)</td>\n            <td><strong>Absence</strong> d'un médicament dont le patient tirerait bénéfice</td>\n            <td><span class=\"kw-ttt\">Anticoagulation</span> non prescrite dans une <span class=\"kw-def\">FA</span> à risque</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Surtout chez la <span class=\"kw-clinique\">personne âgée</span>.</strong> Des listes validées repèrent les <span class=\"kw-def\">PMI</span> : critères de <span class=\"kw-def\">Beers</span> (US), <span class=\"kw-def\">STOPP/START</span> (européen), liste de <span class=\"kw-def\">Laroche</span> (France).</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":0},{"id":"325-4","rang":"B","rubrique":"Définition","titre":"Connaître la prévention des dysfonctionnements du circuit du médicament","contenu":"<p>Le <span class=\"kw-def\">circuit du médicament</span> comporte <span class=\"kw-chiffre\">quatre étapes</span>, chacune source d'erreur : <strong><span class=\"kw-def\">prescription</span> → <span class=\"kw-def\">dispensation</span> → <span class=\"kw-def\">administration</span> → <span class=\"kw-def\">suivi / réévaluation</span></strong>.</p>\n\n      <div class=\"callout callout-info\"><strong>La règle des 5 B</strong> (verbatim Collège) — prévient les dysfonctionnements à l'administration.</div>\n      <table >\n        <thead><tr><th>Règle</th><th>Vérification</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bon <span class=\"kw-def\">patient</span></strong></td><td>Vérifier l'identité, le bon dossier, l'état clinique et biologique</td></tr>\n          <tr><td><strong>Bon <span class=\"kw-def\">médicament</span></strong></td><td>Demander confirmation si illisible ; ne <span class=\"kw-alerte\">jamais</span> administrer un médicament dont on ignore la <span class=\"kw-def\">classe pharmacologique</span></td></tr>\n          <tr><td><strong>Bonne <span class=\"kw-def\">dose</span></strong></td><td>Posologie adaptée au <span class=\"kw-chiffre\">poids</span>, à l'<span class=\"kw-chiffre\">âge</span> et au mode d'administration</td></tr>\n          <tr><td><strong>Bonne <span class=\"kw-def\">voie</span></strong></td><td>Voie compatible avec le médicament et l'état clinique</td></tr>\n          <tr><td><strong>Bon <span class=\"kw-def\">moment</span></strong></td><td>Vérifier le <span class=\"kw-def\">plan de soins</span> ; <strong>tracer</strong> l'administration (ou la non-administration)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 321 — Bon usage du médoc et des thérapeutiques non médicamenteuses · 322 — Décision thérapeutique personnalisée</em></p>","frequence":0},{"id":"325-5","rang":"B","rubrique":"Physiopathologie","titre":"Définir et expliquer les mécanismes généraux des principales pathologies induites par les médicaments","contenu":"<p>On distingue <strong>deux grands mécanismes</strong> d'EIM, qui orientent la prévisibilité et la prévention :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Type A — « Augmented »</th><th>Type B — « Bizarre »</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td><span class=\"kw-def\">Pharmacologique</span> : effet principal exagéré ou effet latéral</td><td><span class=\"kw-def\">Immuno-allergique</span>, idiosyncrasique</td></tr>\n          <tr><td><strong>Prévisible</strong></td><td><span class=\"kw-clinique\">Oui</span> (propriétés connues)</td><td><span class=\"kw-alerte\">Non</span></td></tr>\n          <tr><td><strong>Dose-dépendant</strong></td><td>Oui</td><td>Non</td></tr>\n          <tr><td><strong>Fréquence</strong></td><td><span class=\"kw-chiffre\">Fréquent</span></td><td><span class=\"kw-chiffre\">Rare</span></td></tr>\n          <tr><td><strong>Détection</strong></td><td>Dès les <span class=\"kw-bio\">essais cliniques</span> (avant AMM)</td><td>Souvent <strong>après AMM</strong> (pharmacovigilance)</td></tr>\n          <tr><td><strong>Évitabilité</strong></td><td>Souvent évitable</td><td>Le plus souvent inévitable</td></tr>\n          <tr><td><strong>Exemples</strong></td><td><span class=\"kw-clinique\">Hypoglycémie</span> sous <span class=\"kw-ttt\">insuline</span> ; <span class=\"kw-clinique\">hypokaliémie</span> sous <span class=\"kw-ttt\">thiazidique</span> ; <span class=\"kw-clinique\">sécheresse buccale</span> (effet atropinique des <span class=\"kw-ttt\">anti-H1</span>)</td><td><span class=\"kw-alerte\">Choc anaphylactique</span>, <span class=\"kw-alerte\">toxidermie</span> immuno-allergique</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Réflexe iatrogène — principales pathologies induites par appareil</strong> (« <em>Et si c'était le médicament ?</em> ») :</p>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Médicaments en cause</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Neuro-psychiatrique</span></strong></td>\n            <td>\n              <strong>Sd extrapyramidal :</strong> tous les <span class=\"kw-ttt\">neuroleptiques</span> + neuroleptiques « cachés » (<span class=\"kw-ttt\">métoclopramide</span>, <span class=\"kw-ttt\">métopimazine</span>, <span class=\"kw-ttt\">dompéridone</span>)<br>\n              <strong>Sd confusionnel :</strong> <span class=\"kw-ttt\">benzodiazépines</span>, <span class=\"kw-ttt\">morphiniques</span>, <span class=\"kw-ttt\">corticoïdes</span>, atropiniques<br>\n              <strong>Sd sérotoninergique :</strong> association de 2 <span class=\"kw-ttt\">sérotoninergiques</span> (IRS, IRSNA, <span class=\"kw-ttt\">tramadol</span>, <span class=\"kw-ttt\">triptans</span>, <span class=\"kw-ttt\">lithium</span>)<br>\n              <strong>Sd atropinique :</strong> <span class=\"kw-ttt\">atropine</span>, anti-H1 de 1ʳᵉ génération, imipraminiques\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Cardiaque</span></strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Bradycardie</span> / BAV :</strong> <span class=\"kw-ttt\">β-bloquants</span> (même en collyre), anti-arythmiques (dont <span class=\"kw-ttt\">amiodarone</span>), <span class=\"kw-ttt\">digoxine</span>, anticalciques bradycardisants (<span class=\"kw-ttt\">vérapamil</span>, <span class=\"kw-ttt\">diltiazem</span>)<br>\n              <strong><span class=\"kw-alerte\">Allongement du QT</span> / torsades :</strong> anti-arythmiques, neuroleptiques, <span class=\"kw-ttt\">citalopram</span>, <span class=\"kw-ttt\">moxifloxacine</span>, macrolides, <span class=\"kw-ttt\">méthadone</span><br>\n              <strong>Insuffisance cardiaque :</strong> inotropes négatifs (β-bloquants, <span class=\"kw-ttt\">vérapamil</span>) ; rétention sodée (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">corticoïdes</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Métabolique</span></strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Hypoglycémie</span> :</strong> <span class=\"kw-ttt\">insulines</span>, <span class=\"kw-ttt\">sulfamides</span>, <span class=\"kw-ttt\">glinides</span><br>\n              <strong><span class=\"kw-bio\">Hyperkaliémie</span> :</strong> <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span>, anti-aldostérones, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">héparine</span><br>\n              <strong><span class=\"kw-bio\">Hyponatrémie</span> (SIADH) :</strong> <span class=\"kw-ttt\">diurétiques</span>, IRS, carbamazépine<br>\n              <strong>Acidose lactique :</strong> <span class=\"kw-ttt\">metformine</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Rénale</span></strong></td>\n            <td>\n              <strong>IR fonctionnelle :</strong> <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span>, <span class=\"kw-ttt\">AINS</span> (« triple whammy »)<br>\n              <strong>Nécrose tubulaire :</strong> <span class=\"kw-ttt\">aminosides</span>, <span class=\"kw-imagerie\">produits de contraste iodés</span>, <span class=\"kw-ttt\">cisplatine</span><br>\n              <strong>Néphrite interstitielle immuno-allergique :</strong> <span class=\"kw-ttt\">AINS</span>, β-lactamines, <span class=\"kw-ttt\">IPP</span>, allopurinol\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Hématologique</span></strong></td>\n            <td>\n              <strong><span class=\"kw-alerte\">Agranulocytose</span> :</strong> antithyroïdiens, <span class=\"kw-ttt\">clozapine</span>, <span class=\"kw-ttt\">cotrimoxazole</span>, <span class=\"kw-ttt\">colchicine</span><br>\n              <strong><span class=\"kw-alerte\">Hémorragie</span> :</strong> anticoagulants (<span class=\"kw-ttt\">AVK</span>, <span class=\"kw-ttt\">AOD</span>), antiagrégants, <span class=\"kw-ttt\">héparine</span><br>\n              <strong>Thrombose :</strong> <span class=\"kw-ttt\">estroprogestatifs</span>, THM\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hépatique &amp; musculo-squelettique</strong></td>\n            <td>\n              <strong>Hépatite :</strong> <span class=\"kw-ttt\">paracétamol</span> (surdosage), amoxicilline-clavulanate, antituberculeux, <span class=\"kw-ttt\">statines</span><br>\n              <strong><span class=\"kw-clinique\">Rhabdomyolyse</span> / myalgies :</strong> <span class=\"kw-ttt\">statines</span>, fibrates<br>\n              <strong>Tendinopathie :</strong> <span class=\"kw-ttt\">fluoroquinolones</span> ; <strong>ostéoporose :</strong> <span class=\"kw-ttt\">corticoïdes</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Synthèse fiche source EIM + Collège de Thérapeutique (liste non exhaustive).</em></p>","frequence":0},{"id":"325-6","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des risques iatrogènes","contenu":"<p><strong>Chiffres-clés de la iatrogénie (à retenir pour l'EDN) :</strong></p>\n      <ul>\n        <li>Les EIM sont responsables d'environ <span class=\"kw-chiffre\">10 %</span> des <span class=\"kw-clinique\">hospitalisations</span> ; les accidents iatrogènes médicamenteux représentent <span class=\"kw-chiffre\">0,5 à 2 %</span> des consultations en médecine ambulatoire.</li>\n        <li><strong><span class=\"kw-chiffre\">Un EIM sur deux</span> est évitable</strong> — cible prioritaire de la prévention.</li>\n        <li>La fréquence des EIM <strong>double après <span class=\"kw-chiffre\">65 ans</span></strong> ; un <span class=\"kw-clinique\">sujet âgé</span> a une probabilité d'hospitalisation pour EIM <span class=\"kw-chiffre\">7 fois</span> supérieure à celle d'un sujet jeune.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Enquête <span class=\"kw-def\">ENEIS</span></strong> (événements indésirables graves liés aux soins) :\n      <ul>\n        <li><span class=\"kw-chiffre\">6</span> EIG pour <span class=\"kw-chiffre\">1000</span> jours d'hospitalisation (<span class=\"kw-chiffre\">9</span> en chirurgie, <span class=\"kw-chiffre\">5</span> en médecine) ≈ <strong>1 EIG tous les <span class=\"kw-chiffre\">5 jours</span></strong> dans un service de 30 lits.</li>\n        <li><span class=\"kw-chiffre\">4,5 %</span> des séjours sont causés par un EIG, dont <span class=\"kw-chiffre\">2,5 %</span> par un EIG <strong>évitable</strong>.</li>\n        <li>Les patients <span class=\"kw-clinique\">âgés et fragiles</span> sont les plus exposés aux EIG évitables.</li>\n      </ul></div>\n\n      <div class=\"callout callout-warn\"><strong>Limite à connaître.</strong> La iatrogénie est <strong>difficile à quantifier</strong> (sous-notification, imputabilité incertaine) : les chiffres sont des estimations basses.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique + fiche source.</em></p>","frequence":1},{"id":"325-7","rang":"A","rubrique":"Définition","titre":"Connaître les caractéristiques des EIM chez les personnes âgées","contenu":"<div class=\"callout callout-info\"><strong>Qui est « âgé » ?</strong> Sujet de <span class=\"kw-chiffre\">≥ 75 ans</span>, <strong>ou</strong> de <span class=\"kw-chiffre\">≥ 65 ans</span> polypathologique.</div>\n\n      <p><strong>Pourquoi un sur-risque d'EIM ?</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Polymédication</span></strong> (polypathologie, prescripteurs multiples) : le risque d'EIM croît <strong>exponentiellement</strong> avec le nombre de médicaments.</li>\n        <li><strong>Modifications <span class=\"kw-def\">pharmacocinétiques</span></strong> : ↓ du <span class=\"kw-bio\">débit de filtration glomérulaire</span> (accumulation des médicaments à élimination rénale — <span class=\"kw-ttt\">aminosides</span>, <span class=\"kw-ttt\">lithium</span>) ; <span class=\"kw-bio\">hypoalbuminémie</span> (dénutrition) → ↑ fraction libre (<span class=\"kw-ttt\">AVK</span>, <span class=\"kw-ttt\">sulfamides</span>) ; ↓ volume de distribution si <span class=\"kw-clinique\">déshydratation</span> ; ↓ métabolisme hépatique.</li>\n        <li><strong>Modifications <span class=\"kw-def\">pharmacodynamiques</span></strong> : sensibilité accrue du SNC, fragilité homéostatique.</li>\n        <li><strong>Présentation <span class=\"kw-alerte\">atypique / frustre</span></strong> : <span class=\"kw-clinique\">chute</span>, <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">hypotension orthostatique</span> peuvent révéler l'EIM.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Prévention.</strong> Hiérarchiser les objectifs, <strong>limiter la polymédication</strong> et <span class=\"kw-def\">déprescrire</span> ; adapter la posologie au <span class=\"kw-bio\">DFG</span> (Cockcroft) ; <strong>éviter les médicaments inappropriés</strong> (<span class=\"kw-ci\">sédatifs</span>, <span class=\"kw-ci\">anticholinergiques</span>, antihypertenseurs centraux) ; privilégier les médicaments <strong>anciens, bien évalués</strong>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (La personne âgée).</em></p>","frequence":0},{"id":"325-8","rang":"A","rubrique":"Définition","titre":"Connaître les objectifs et principes de la pharmacovigilance","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> La <span class=\"kw-def\">pharmacovigilance (PV)</span> est la <strong>surveillance des médicaments après leur commercialisation (post-AMM)</strong>, la prévention et la gestion du risque d'EIM.</div>\n\n      <p><strong>Les 5 temps de la <span class=\"kw-def\">PV</span> :</strong> <span class=\"kw-def\">détection</span> (<span class=\"kw-def\">signal</span>) → <span class=\"kw-def\">évaluation</span> (quantification) → <span class=\"kw-def\">compréhension</span> (mécanisme, facteurs favorisants) → <span class=\"kw-def\">prévention</span> → <span class=\"kw-def\">gestion</span> du risque. Elle repose sur la <strong><span class=\"kw-def\">notification spontanée</span></strong> (et non sur des essais), seul moyen de détecter les <span class=\"kw-def\">EIM</span> <strong>rares</strong> ou <strong>retardés</strong> non vus avant l'<span class=\"kw-def\">AMM</span>.</p>\n\n      <p><strong>Organisation à trois échelons :</strong></p>\n      <table >\n        <thead><tr><th>Échelon</th><th>Structure</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td>Régional</td><td><span class=\"kw-def\">CRPV</span> (Centre Régional de PV)</td><td>Recueil, validation et évaluation des EIM ; aide au diagnostic et à l'<span class=\"kw-def\">imputabilité</span> ; conseil et formation</td></tr>\n          <tr><td>National</td><td><span class=\"kw-def\">ANSM</span></td><td>Coordonne le système ; décide des mesures : restriction, <span class=\"kw-ci\">contre-indication</span>, <span class=\"kw-alerte\">retrait</span>, <span class=\"kw-def\">plan de gestion des risques (PGR)</span></td></tr>\n          <tr><td>Européen</td><td><span class=\"kw-def\">EMA</span> / <span class=\"kw-def\">PRAC</span></td><td>Centralise les décisions à l'échelle de l'UE (le PRAC est l'organe décisionnel européen)</td></tr>\n        </tbody>\n      </table>\n      <p>Les <strong>firmes pharmaceutiques</strong> ont l'obligation de posséder une structure de PV et transmettent les EIM à l'ANSM.</p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":1},{"id":"325-9","rang":"B","rubrique":"Définition","titre":"Connaître le principe d’imputabilité","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> L'<span class=\"kw-def\">imputabilité</span> est l'analyse <strong>individuelle, cas par cas</strong>, du lien de causalité entre un médicament et un EIM donné (méthode <span class=\"kw-def\">probabiliste</span>). Elle ne juge <strong>pas</strong> la dangerosité du médicament dans l'absolu.</div>\n\n      <p><strong>Imputabilité intrinsèque (I)</strong> — tirée du cas observé, croise deux scores :</p>\n      <table >\n        <thead><tr><th>Score</th><th>Composantes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Chronologique (C)</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Challenge</span> :</strong> délai d'apparition évocateur<br>\n              <strong><span class=\"kw-def\">Dechallenge</span> :</strong> évolution à l'<span class=\"kw-clinique\">arrêt</span> du médicament<br>\n              <strong><span class=\"kw-def\">Rechallenge</span> :</strong> <span class=\"kw-alerte\">réapparition</span> à la réintroduction\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sémiologique (S)</strong></td>\n            <td>Sémiologie évocatrice ; existence d'un <span class=\"kw-etio\">facteur favorisant</span> ; <strong>absence d'autre étiologie</strong> après bilan ; tests complémentaires fiables</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le croisement C × S donne le <strong>score I de <span class=\"kw-chiffre\">I0</span> à <span class=\"kw-chiffre\">I4</span></strong> : I0 « paraissant exclue », I1 « possible », I2 « plausible », I3 « vraisemblable », I4 « très vraisemblable ».</p>\n\n      <p><strong>Imputabilité extrinsèque</strong> — repose sur des données <strong>externes</strong> (littérature, banques de PV) : score <span class=\"kw-def\">bibliographique</span> de <span class=\"kw-chiffre\">B0</span> (jamais décrit) à <span class=\"kw-chiffre\">B3</span> (effet notoire).</p>\n\n      <div class=\"callout callout-warn\"><strong>Argument fort.</strong> Certains médicaments sont des <span class=\"kw-etio\">inducteurs préférentiels</span> d'un type d'EIM (utile surtout en cas de polymédication). L'<span class=\"kw-def\">érythème pigmenté fixe</span> est <strong>pathognomonique</strong> d'une cause médicamenteuse.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique + fiche source (imputabilité).</em></p>","frequence":0},{"id":"325-10","rang":"A","rubrique":"Définition","titre":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à un médicament","contenu":"<p>Le réflexe « <strong>Quoi / à qui / par qui / comment</strong> » de la déclaration de pharmacovigilance :</p>\n      <table >\n        <thead><tr><th></th><th>Réponse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Quoi ?</strong></td><td><strong>Tous les <span class=\"kw-def\">EIM</span></strong>, <span class=\"kw-alerte\">graves</span> ou non, <span class=\"kw-def\">attendus</span> ou non. Ne <strong>jamais</strong> oublier : les EIM <span class=\"kw-alerte\">graves</span>, les <span class=\"kw-def\">inattendus</span>, et ceux des médicaments commercialisés depuis <span class=\"kw-chiffre\">moins de 5 ans</span>.</td></tr>\n          <tr><td><strong>À qui ?</strong></td><td>Au <span class=\"kw-def\">CRPV</span> — <strong><span class=\"kw-alerte\">jamais aux firmes</span></strong>.</td></tr>\n          <tr><td><strong>Par qui ?</strong></td><td><strong><span class=\"kw-def\">Obligatoire</span></strong> : médecins, chirurgiens-dentistes, sages-femmes, pharmaciens. <strong><span class=\"kw-def\">Possible</span></strong> : autres professionnels de santé et <strong>patients</strong> (ou associations).</td></tr>\n          <tr><td><strong>Comment ?</strong></td><td>Portail <span class=\"kw-def\">signalement-sante.gouv.fr</span>, formulaire <span class=\"kw-def\">Cerfa</span>, courrier / fax / appli <span class=\"kw-def\">CRPV</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Rappel piège.</strong> <span class=\"kw-def\">Gravité</span> (conséquences) ≠ <span class=\"kw-def\">sévérité</span> (intensité). La notification est une <strong>obligation légale</strong>, pas une option.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":1},{"id":"325-11","rang":"A","rubrique":"Définition","titre":"Expliquer les objectifs et principes de l’addictovigilance (voir items 77, 78 et 80)","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> L'<span class=\"kw-def\">addictovigilance (AV)</span> est la <span class=\"kw-def\">surveillance</span>, l'<span class=\"kw-def\">évaluation</span>, la prévention et la gestion du risque d'<span class=\"kw-alerte\">abus</span>, de <span class=\"kw-alerte\">dépendance</span> et d'<span class=\"kw-alerte\">usage détourné</span> liés à <strong>tout <span class=\"kw-def\">produit psychoactif</span></strong> (<span class=\"kw-ttt\">médicament</span>, substance, plante).</div>\n\n      <ul>\n        <li><strong>Champ :</strong> tous les produits à <span class=\"kw-def\">effet psychoactif</span>, <strong>à l'exclusion de l'<span class=\"kw-etio\">alcool éthylique</span> et du <span class=\"kw-etio\">tabac</span></strong>.</li>\n        <li><strong>Réseau :</strong> les <span class=\"kw-def\">CEIP-A</span> (Centres d'Évaluation et d'Information sur la Pharmacodépendance et d'Addictovigilance), <strong>pilotés par l'<span class=\"kw-def\">ANSM</span></strong>.</li>\n        <li><strong>But :</strong> adapter les conditions de <span class=\"kw-def\">prescription</span> et de <span class=\"kw-def\">délivrance</span>, informer les professionnels et le public.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 77 — Addiction aux psychotropes · 78 — Addication aux drogues · 80 — Dopage</em></p>","frequence":0},{"id":"325-12","rang":"A","rubrique":"Définition","titre":"Connaître le mécanisme de déclaration d’un abus, une dépendance et des usages détournés liés à la consommation de toutes les substances ou plantes ayant un effet psychoactif, ainsi que de tous les médicaments ou autres produits en contenant","contenu":"<p>Mécanisme de déclaration d'addictovigilance (« <strong>Quoi / à qui / par qui / comment</strong> ») :</p>\n      <table >\n        <thead><tr><th></th><th>Réponse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Quoi ?</strong></td><td><span class=\"kw-alerte\">Abus</span> (<span class=\"kw-clinique\">complication somatique</span> ou <span class=\"kw-clinique\">psychiatrique</span>), <span class=\"kw-alerte\">dépendance</span> (<span class=\"kw-clinique\">perte de contrôle</span>), <span class=\"kw-alerte\">usage détourné</span> (mésusage récréatif, alimentation d'un trafic). <strong>Obligatoire pour les <span class=\"kw-alerte\">cas graves</span></strong> (ex. <span class=\"kw-alerte\">AVC</span> sous <span class=\"kw-ttt\">cocaïne</span>, complications du <span class=\"kw-ttt\">protoxyde d'azote</span>, <span class=\"kw-alerte\">passage à l'acte suicidaire</span>).</td></tr>\n          <tr><td><strong>À qui ?</strong></td><td>Au <span class=\"kw-def\">CEIP-A</span>.</td></tr>\n          <tr><td><strong>Par qui ?</strong></td><td><strong>Tout <span class=\"kw-def\">médecin</span></strong> ayant connaissance d'un cas, quelle que soit sa spécialité.</td></tr>\n          <tr><td><strong>Comment ?</strong></td><td>Portail <span class=\"kw-def\">signalement-sante.gouv.fr</span> ou site <span class=\"kw-def\">addictovigilance.fr</span> (courrier, mail, fax).</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":0},{"id":"325-13","rang":"B","rubrique":"Définition","titre":"Connaître les objectifs et principes de la matériovigilance (voir item 181)","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> La <span class=\"kw-def\">matériovigilance (MV)</span> est le <span class=\"kw-def\">signalement</span> et l'<span class=\"kw-def\">évaluation</span> des <span class=\"kw-alerte\">incidents</span> survenant lors de l'utilisation d'un <span class=\"kw-def\">dispositif médical (DM)</span> mis sur le marché avec un <strong>marquage <span class=\"kw-def\">CE</span></strong>.</div>\n\n      <ul>\n        <li><strong>Objectifs :</strong> garantir la sécurité d'<span class=\"kw-def\">approvisionnement</span>, de <span class=\"kw-def\">stockage</span>, de mise en service et de dispensation des <span class=\"kw-def\">DM</span>, le maintien de leurs <span class=\"kw-def\">performances</span> et la formation des utilisateurs.</li>\n        <li><strong>Circuit hospitalier :</strong> une <span class=\"kw-def\">fiche de MV</span> est adressée au <span class=\"kw-def\">correspondant local de matériovigilance</span> de l'établissement → transmission à l'<span class=\"kw-def\">ANSM</span>.</li>\n        <li>Si le <span class=\"kw-def\">DM</span> <strong>administre un médicament</strong> (ex. <span class=\"kw-ttt\">stent actif</span>), le <span class=\"kw-def\">CRPV</span> est aussi informé.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 181 — Sécurité sanitaire des produits - Veille sanitaire</em></p>","frequence":0},{"id":"325-14","rang":"A","rubrique":"Définition","titre":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à des biomatériaux","contenu":"<p>Déclaration de matériovigilance (« <strong>Quoi / à qui / par qui / comment</strong> ») :</p>\n      <table >\n        <thead><tr><th></th><th>Réponse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Quoi ?</strong></td><td>Tout <strong>incident ou risque d'incident <span class=\"kw-alerte\">grave</span></strong> mettant en cause un <span class=\"kw-def\">DM</span> : ayant entraîné ou susceptible d'entraîner un <span class=\"kw-alerte\">décès</span>, une <span class=\"kw-alerte\">dégradation grave</span> de l'état de santé, une <span class=\"kw-clinique\">hospitalisation</span>, une <span class=\"kw-clinique\">intervention</span>, une <span class=\"kw-clinique\">malformation congénitale</span> ou une <span class=\"kw-alerte\">menace vitale</span>.</td></tr>\n          <tr><td><strong>Quand ?</strong></td><td><strong><span class=\"kw-alerte\">Sans délai</span></strong> (incident <span class=\"kw-alerte\">grave</span> avéré <em>ou</em> potentiel).</td></tr>\n          <tr><td><strong>À qui ?</strong></td><td>À l'<span class=\"kw-def\">ANSM</span> — <strong><span class=\"kw-alerte\">pas aux firmes</span></strong> ; via le <span class=\"kw-def\">correspondant local de MV</span> à l'hôpital, ou directement à l'<span class=\"kw-def\">ANSM</span> en libéral.</td></tr>\n          <tr><td><strong>Comment ?</strong></td><td>Portail <span class=\"kw-def\">signalement-sante.gouv.fr</span>.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":1},{"id":"325-15","rang":"A","rubrique":"Prise en charge","titre":"Identifier une erreur médicamenteuse, ses mécanismes et connaître les conséquences","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> Une <span class=\"kw-def\">erreur médicamenteuse (EM)</span> est un <span class=\"kw-def\">événement évitable</span> par définition, résultant d'un <span class=\"kw-def\">dysfonctionnement non intentionnel</span> durant le processus de soins. Elle peut survenir à <strong>toute étape</strong> du circuit (<span class=\"kw-def\">prescription</span>, <span class=\"kw-def\">dispensation</span>, <span class=\"kw-def\">administration</span>, <span class=\"kw-def\">suivi</span>).</div>\n\n      <p><strong>Deux statuts :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Avérée</span></strong> : le patient a reçu le mauvais médicament, la mauvaise dose, la mauvaise voie ou le mauvais schéma.</li>\n        <li><strong>Potentielle</strong> : l'erreur a été <strong><span class=\"kw-def\">interceptée</span></strong> avant l'administration.</li>\n      </ul>\n\n      <p><strong>Conséquences :</strong> l'EM est à l'origine d'un <span class=\"kw-alerte\">risque</span>, voire d'un <span class=\"kw-alerte\">EIM</span> avéré. Elle est habituellement <strong><span class=\"kw-etio\">multifactorielle</span></strong> (<span class=\"kw-etio\">facteurs humains</span>, <span class=\"kw-etio\">environnementaux</span>, <span class=\"kw-etio\">organisationnels</span>).</p>\n\n      <div class=\"callout callout-warn\"><strong>CAT devant une EM (verbatim Collège) :</strong> la <strong>diagnostiquer</strong> → <strong>traiter les conséquences</strong> → <strong>prévenir la récidive</strong> → la <strong>déclarer au CRPV</strong>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 4 — Sécurité du patient, gestions des risques, EI · 5 — Gestion des erreurs et plaintes, aléa thérapeutique</em></p>","frequence":0},{"id":"325-16","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une erreur médicamenteuse et de son signalement","contenu":"<p>Une <span class=\"kw-def\">erreur médicamenteuse</span> (<span class=\"kw-def\">EM</span>) est un <strong>écart évitable</strong> entre ce qui aurait dû être fait et ce qui a été réellement fait durant la prise en charge médicamenteuse. Toute EM — <strong>avec ou sans <span class=\"kw-def\">EIM</span></strong> — doit faire l'objet d'une <strong>déclaration au <span class=\"kw-def\">CRPV</span></strong>.</p>\n\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Culture positive de l'erreur</span></strong> (approche <strong>systémique et non punitive</strong>) : repérer, transmettre, corriger — <span class=\"kw-def\">déculpabiliser</span> pour mieux prévenir. Trois temps :\n      <ul>\n        <li><strong>Analyse des <span class=\"kw-alerte\">EIG</span></strong> : recherche des <span class=\"kw-etio\">facteurs contributifs</span> (souvent <span class=\"kw-etio\">multifactoriels</span>).</li>\n        <li><strong>Revue de Mortalité et de Morbidité (<span class=\"kw-def\">RMM</span>)</strong> : analyse <span class=\"kw-def\">collective</span>, <span class=\"kw-def\">rétrospective</span> et <span class=\"kw-def\">systémique</span> ; <strong>obligatoire</strong> en anesthésie-réanimation, chirurgie et cancérologie pour la <span class=\"kw-def\">certification</span>.</li>\n        <li><strong>Information + <span class=\"kw-def\">plan d'action</span></strong> de réduction des risques.</li>\n      </ul></div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":0},{"id":"325-17","rang":"A","rubrique":"Prise en charge","titre":"Identifier et prévenir une erreur sur le circuit du médicament","contenu":"<p>Le <span class=\"kw-def\">circuit du médicament</span> — <strong><span class=\"kw-def\">prescription</span> → <span class=\"kw-def\">dispensation</span> → <span class=\"kw-def\">administration</span> → <span class=\"kw-def\">suivi</span></strong> — est sécurisé à chaque maillon.</p>\n\n      <p><strong>Mesures de prévention :</strong></p>\n      <ul>\n        <li>Appliquer la <strong>règle des <span class=\"kw-def\">5 B</span></strong> à l'administration (bon patient / médicament / dose / voie / moment).</li>\n        <li><strong><span class=\"kw-def\">Conciliation médicamenteuse</span></strong> aux <span class=\"kw-def\">points de transition</span> (admission, sortie) pour éviter les divergences.</li>\n        <li><strong><span class=\"kw-def\">Informatisation</span></strong> de la prescription (alertes <span class=\"kw-alerte\">interactions</span>, lisibilité).</li>\n        <li><strong>Double contrôle</strong> des <span class=\"kw-alerte\">médicaments à risque</span> (<span class=\"kw-ttt\">anticoagulants</span>, <span class=\"kw-ttt\">insuline</span>, <span class=\"kw-ttt\">chimiothérapies</span>, <span class=\"kw-ttt\">électrolytes concentrés</span>).</li>\n        <li><strong>Analyse a posteriori</strong> en <span class=\"kw-def\">RMM</span> + plan d'action.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Posture clé.</strong> Démarche <strong>systémique et non culpabilisante</strong> : on cherche la faille du système, pas le coupable. Toute EM (avérée ou interceptée) se déclare au <span class=\"kw-def\">CRPV</span>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 4 — Sécurité du patient, gestions des risques, EI · 5 — Gestion des erreurs et plaintes, aléa thérapeutique</em></p>","frequence":0},{"id":"325-18","rang":"B","rubrique":"Définition","titre":"Connaître la définition de la contrefaçon d’un médicament","contenu":"<div class=\"callout callout-info\"><strong>Définition (OMS).</strong> Un <span class=\"kw-def\">médicament falsifié</span> (« <span class=\"kw-def\">contrefaisant</span> ») est un produit <strong>travesti prenant le masque d'un <span class=\"kw-def\">vrai médicament</span></strong> — même <span class=\"kw-def\">nom de marque</span> (ou proche), même <span class=\"kw-def\">conditionnement</span>, même <span class=\"kw-def\">présentation</span> — destiné à <strong>duper le consommateur</strong> (définition <span class=\"kw-def\">OMS</span>).</div>\n\n      <p><strong>Motivations des acquéreurs :</strong></p>\n      <ul>\n        <li><strong>Économiques</strong> : obtenir un <span class=\"kw-chiffre\">prix nettement inférieur</span> au <span class=\"kw-def\">prix officinal</span>.</li>\n        <li><strong>Personnelles</strong> : se procurer des produits <span class=\"kw-etio\">illégaux</span> (<span class=\"kw-ttt\">dopants</span>, <span class=\"kw-ttt\">hormones</span>, <span class=\"kw-ttt\">anorexigènes</span>) ou des médicaments sur ordonnance achetés <strong>en toute discrétion</strong> (<span class=\"kw-clinique\">troubles de l'érection</span>…).</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":0},{"id":"325-19","rang":"B","rubrique":"Définition","titre":"Apprécier les risques liés à la contrefaçon des médicaments","contenu":"<p><strong>Risques sanitaires</strong> du médicament falsifié :</p>\n      <ul>\n        <li>Le plus souvent <strong>aucun <span class=\"kw-bio\">principe actif</span></strong> → <span class=\"kw-alerte\">échec thérapeutique</span> dramatique.</li>\n        <li><span class=\"kw-bio\">Sous-dosage</span> → émergence de <span class=\"kw-alerte\">résistances</span> (<span class=\"kw-ttt\">antibiotiques</span>, <span class=\"kw-ttt\">antipaludiques</span>, <span class=\"kw-ttt\">antirétroviraux</span>).</li>\n        <li>Présence de <span class=\"kw-alerte\">composés toxiques</span> ou d'excipients nocifs (ex. <span class=\"kw-etio\">éthylène glycol</span> dans des sirops).</li>\n      </ul>\n\n      <p><strong>Épidémiologie &amp; circuits :</strong></p>\n      <ul>\n        <li><span class=\"kw-chiffre\">20 à 30 %</span> du marché en Afrique sub-saharienne et Asie du Sud-Est ; davantage en zones de conflit.</li>\n        <li>Pays développés touchés via <strong>Internet</strong> : près de la <span class=\"kw-chiffre\">moitié</span> des médicaments vendus hors sites légaux seraient des faux ; fraude sur les médicaments <span class=\"kw-etio\">onéreux</span> (<span class=\"kw-ttt\">anticancéreux</span>, <span class=\"kw-ttt\">immunosuppresseurs</span>).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>En pratique.</strong> Suspecter une contrefaçon devant une <span class=\"kw-alerte\">inefficacité</span> ou des EI <span class=\"kw-alerte\">inattendus</span> ; <strong>déclarer au <span class=\"kw-def\">CRPV</span></strong> ; conseiller au patient de s'approvisionner <strong>uniquement en pharmacie</strong>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>","frequence":0},{"id":"325-20","rang":"B","rubrique":"Définition","titre":"Définir la notion de responsabilité sans faute et le rôle de l’Office national d’indemnisation des accidents médicaux (ONIAM)","contenu":"<div class=\"callout callout-info\"><strong><span class=\"kw-def\">Aléa médical</span> (thérapeutique).</strong> <span class=\"kw-def\">Événement indésirable</span> <strong><span class=\"kw-def\">imprévisible</span></strong>, <strong><span class=\"kw-def\">non fautif</span></strong>, survenant au cours d'un acte médical et causant un <span class=\"kw-clinique\">dommage</span> <strong>indépendant de l'état pathologique</strong> du patient.</div>\n\n      <p><strong><span class=\"kw-def\">Responsabilité sans faute</span> :</strong> notion introduite pour permettre d'indemniser ces complications non fautives. La <strong><span class=\"kw-def\">loi Kouchner</span> du <span class=\"kw-chiffre\">4 mars 2002</span></strong> (droits des patients) ouvre l'indemnisation de l'<span class=\"kw-def\">aléa médical</span> au titre de la <strong><span class=\"kw-def\">solidarité nationale</span></strong>.</p>\n\n      <p><strong>Rôle de l'<span class=\"kw-def\">ONIAM</span></strong> (Office National d'Indemnisation des Accidents Médicaux) :</p>\n      <ul>\n        <li>Indemnise les <strong>aléas thérapeutiques</strong> (accidents médicaux <strong>sans faute</strong>) au titre de la solidarité nationale.</li>\n        <li>Autres missions : indemnisation des <span class=\"kw-etio\">transfusés contaminés</span> (<span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHC</span>), du <span class=\"kw-etio\">benfluorex (Médiator®)</span>, des victimes de <span class=\"kw-etio\">vaccinations obligatoires</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>À distinguer.</strong> Si le dommage est lié à une <span class=\"kw-alerte\">faute</span> (après expertise) → indemnisation par l'<strong>assureur du responsable</strong>, et non par l'ONIAM.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 5 — Gestion des erreurs et plaintes, aléa thérapeutique</em></p>","frequence":1},{"id":"325-21","rang":"B","rubrique":"Définition","titre":"Connaître les modalités de saisine de l’ONIAM","contenu":"<p><strong>Saisine — <span class=\"kw-def\">procédure gratuite</span></strong> via la <span class=\"kw-def\">CRCI</span> (Commission régionale de Conciliation et d'Indemnisation des accidents médicaux), qui statue d'abord sur la <strong><span class=\"kw-def\">recevabilité</span></strong> de la demande.</p>\n\n      <p><strong>Seuil de gravité = taux d'<span class=\"kw-def\">AIPP</span></strong> (atteinte permanente à l'intégrité physique ou psychique) :</p>\n      <table >\n        <thead><tr><th>Gravité</th><th>Voie d'indemnisation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">≤ 24 %</span></td><td><span class=\"kw-def\">Indemnisation amiable</span> proposée par la <span class=\"kw-def\">CRCI</span> (à l'amiable ou voie judiciaire)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 24 %</span></td><td><span class=\"kw-def\">Expertise</span> → indemnisation de l'<span class=\"kw-def\">aléa</span> par l'<span class=\"kw-def\">ONIAM</span> (<span class=\"kw-def\">solidarité nationale</span>)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Atout de la procédure.</strong> Elle permet, dans <strong>près d'<span class=\"kw-chiffre\">un cas sur deux</span></strong>, un <span class=\"kw-def\">règlement amiable</span> du litige. En cas de <span class=\"kw-alerte\">faute</span>, la <span class=\"kw-def\">CRCI</span> oriente vers l'<strong>assureur du responsable</strong>.</div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Thérapeutique (Bon Usage du Médicament).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 5 — Gestion des erreurs et plaintes, aléa thérapeutique</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"13cdef50f0d4","n":325,"o":"325-1","u":"Définition","t":"Connaître la définition d’un effet indésirable médicamenteux (EIM)","q":"Quelles sont les obligations légales en cas de survenue d'un effet indésirable médicamenteux (EIM) ?","a":"<p>La survenue de tout EIM, <strong>quelle qu'en soit la gravité</strong>, impose une <strong>déclaration immédiate au Centre Régional de Pharmacovigilance (CRPV)</strong>. C'est une obligation légale.</p>"},{"i":"14d027225862","n":325,"o":"325-1","u":"Définition","t":"Connaître la définition d’un effet indésirable médicamenteux (EIM)","q":"Quelle est la définition d'un effet indésirable médicamenteux (EIM) ?","a":"<p>Un effet indésirable médicamenteux (EIM) est une réaction <strong>nocive</strong> et <strong>non voulue</strong> à un médicament.</p><p>Il peut survenir lors d'une utilisation <strong>conforme à l'AMM</strong>, ou lors de tout autre usage comme un <strong>surdosage</strong>, un <strong>mésusage</strong>, un <strong>abus</strong> ou une <strong>erreur médicamenteuse</strong>.</p>"},{"i":"aff4bc4d6aa1","n":325,"o":"325-1","u":"Définition","t":"Connaître la définition d’un effet indésirable médicamenteux (EIM)","q":"Comment distinguer la gravité de la sévérité d'un effet indésirable médicamenteux (EIM) ?","a":"<ul><li>La <strong>gravité</strong> d'un EIM renvoie à ses <strong>conséquences</strong> (ex : décès, mise en jeu du pronostic vital, invalidité, hospitalisation).</li><li>La <strong>sévérité</strong> d'un EIM renvoie uniquement à l'<strong>intensité du symptôme</strong>.</li></ul>"},{"i":"09964d5fc30d","n":325,"o":"325-10","u":"Définition","t":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à un médicament","q":"Quelle est la nuance à connaître concernant la gravité et la sévérité d'un effet indésirable médicamenteux ?","a":"<p>Il est important de distinguer la <strong>gravité</strong>, qui se réfère aux <strong>conséquences de l'EIM</strong> (ex: hospitalisation, mise en jeu du pronostic vital), de la <strong>sévérité</strong>, qui concerne l'<strong>intensité de l'EIM</strong> lui-même.</p>"},{"i":"3665b0557a8c","n":325,"o":"325-10","u":"Définition","t":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à un médicament","q":"Qui est concerné par l'obligation de déclaration en pharmacovigilance en France et qui peut également déclarer ?","a":"<ul><li>La déclaration est <strong>obligatoire</strong> pour les <strong>médecins, chirurgiens-dentistes, sages-femmes et pharmaciens</strong>.</li><li>Elle est <strong>possible</strong> pour les <strong>autres professionnels de santé</strong> et les <strong>patients (ou leurs associations)</strong>.</li></ul>"},{"i":"4b56986f2e77","n":325,"o":"325-10","u":"Définition","t":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à un médicament","q":"Quels types d'effets indésirables médicamenteux (EIM) doivent être déclarés en pharmacovigilance ?","a":"<p>Tous les EIM doivent être déclarés, qu'ils soient <strong>graves ou non</strong>, et qu'ils soient <strong>attendus ou non</strong>. Une attention particulière doit être portée aux <strong>EIM graves</strong>, aux <strong>EIM inattendus</strong>, et à ceux concernant des <strong>médicaments commercialisés depuis moins de 5 ans</strong>.</p>"},{"i":"b402d9bb7206","n":325,"o":"325-10","u":"Définition","t":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à un médicament","q":"Par quels moyens techniques peut-on effectuer une déclaration de pharmacovigilance ?","a":"<p>La déclaration peut être réalisée via le <strong>portail signalement-sante.gouv.fr</strong>, par le dépôt d'un <strong>formulaire Cerfa</strong>, ou encore par <strong>courrier, fax ou l'application mobile du CRPV</strong>.</p>"},{"i":"db31b46de742","n":325,"o":"325-10","u":"Définition","t":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à un médicament","q":"À quelle autorité doit-on déclarer un effet indésirable médicamenteux suspecté ?","a":"<p>La déclaration doit être effectuée auprès du <strong>CRPV (Centre Régional de Pharmacovigilance)</strong>. Il ne faut <strong>jamais la faire aux firmes pharmaceutiques</strong>.</p>"},{"i":"0339e4cdec66","n":325,"o":"325-11","u":"Définition","t":"Expliquer les objectifs et principes de l’addictovigilance (voir items 77, 78 et 80)","q":"Quels sont les objectifs principaux de l'addictovigilance ?","a":"<ul><li>Adapter les conditions de <strong>prescription et de délivrance</strong> des produits psychoactifs.</li><li>Informer les <strong>professionnels de santé</strong> et le <strong>public</strong> sur les risques liés à ces produits.</li></ul>"},{"i":"0bdcab05b2e6","n":325,"o":"325-11","u":"Définition","t":"Expliquer les objectifs et principes de l’addictovigilance (voir items 77, 78 et 80)","q":"Qu'est-ce que l'addictovigilance ?","a":"<p>L'addictovigilance est l'ensemble des activités de <strong>surveillance</strong>, d'<strong>évaluation</strong>, de <strong>prévention</strong> et de <strong>gestion du risque</strong> d'abus, de dépendance et d'usage détourné liés à tout produit <strong>psychoactif</strong>.</p>"},{"i":"16ec5a202a75","n":325,"o":"325-11","u":"Définition","t":"Expliquer les objectifs et principes de l’addictovigilance (voir items 77, 78 et 80)","q":"Quelle est l'organisation de l'addictovigilance en France ?","a":"<p>L'addictovigilance est structurée autour des <strong>CEIP-A</strong> (Centres d'Évaluation et d'Information sur la Pharmacodépendance et d'Addictovigilance), pilotés par l'<strong>ANSM</strong> (Agence Nationale de Sécurité du Médicament et des produits de santé).</p>"},{"i":"1d7c116aee03","n":325,"o":"325-11","u":"Définition","t":"Expliquer les objectifs et principes de l’addictovigilance (voir items 77, 78 et 80)","q":"Quels types de produits sont concernés par l'addictovigilance en France ?","a":"<p>L'addictovigilance concerne <strong>tous les produits à effet psychoactif</strong>, incluant médicaments, substances et plantes, à l'exception spécifique de l'alcool éthylique et du tabac.</p>"},{"i":"4c58ad6e8518","n":325,"o":"325-12","u":"Définition","t":"Connaître le mécanisme de déclaration d’un abus, une dépendance et des usages détournés liés à la consommation de toutes les substances ou plantes ayant un effet psychoactif, ainsi que de tous les médicaments ou autres produits en contenant","q":"En addictovigilance, quels sont les trois principaux types d'événements indésirables liés aux substances psychoactives ou aux médicaments qui doivent être déclarés ?","a":"<p>Les trois principaux types d'événements indésirables devant être déclarés en addictovigilance sont :</p><ul><li>L'<strong>abus</strong> : caractérisé par une complication <strong>somatique</strong> ou <strong>psychiatrique</strong>.</li><li>La <strong>dépendance</strong> : définie par une <strong>perte de contrôle</strong> de l'usage.</li><li>L'<strong>usage détourné</strong> : correspondant à un <strong>mésusage récréatif</strong> ou à l'<strong>alimentation d'un trafic</strong>.</li></ul>"},{"i":"71ef999b5287","n":325,"o":"325-12","u":"Définition","t":"Connaître le mécanisme de déclaration d’un abus, une dépendance et des usages détournés liés à la consommation de toutes les substances ou plantes ayant un effet psychoactif, ainsi que de tous les médicaments ou autres produits en contenant","q":"Quel type d'événement indésirable lié aux substances psychoactives entraîne une obligation de déclaration en addictovigilance ?","a":"<p>La déclaration devient <strong>obligatoire</strong> pour les <strong>cas graves</strong> d'abus, de dépendance ou d'usage détourné. Des exemples incluent un <strong>AVC sous cocaïne</strong>, des complications sévères liées au <strong>protoxyde d'azote</strong>, ou un <strong>passage à l'acte suicidaire</strong>.</p>"},{"i":"8925c6603f79","n":325,"o":"325-12","u":"Définition","t":"Connaître le mécanisme de déclaration d’un abus, une dépendance et des usages détournés liés à la consommation de toutes les substances ou plantes ayant un effet psychoactif, ainsi que de tous les médicaments ou autres produits en contenant","q":"Qui doit déclarer un événement indésirable lié aux substances psychoactives au système d'addictovigilance et par quels moyens ?","a":"<p>La déclaration doit être faite par <strong>tout médecin</strong> ayant connaissance d'un cas, quelle que soit sa spécialité. Elle s'effectue auprès du <strong>CEIP-A</strong> (Centre d'Evaluation et d'Information sur la Pharmacodépendance - Addictovigilance) via le portail <strong>signalement-sante.gouv.fr</strong> ou le site <strong>addictovigilance.fr</strong> (par courrier, e-mail ou fax).</p>"},{"i":"63f512a83b84","n":325,"o":"325-14","u":"Définition","t":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à des biomatériaux","q":"À quelle autorité doit être adressée la déclaration de matériovigilance concernant un biomatériau en France ?","a":"<p>La déclaration de matériovigilance doit être adressée à l'<strong>ANSM (Agence nationale de sécurité du médicament et des produits de santé)</strong>. Elle <strong>ne doit pas</strong> être envoyée aux firmes fabricantes.</p>"},{"i":"722b440a8081","n":325,"o":"325-14","u":"Définition","t":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à des biomatériaux","q":"Par quels moyens peut-on déclarer un incident de matériovigilance lié à un biomatériau en France, et quel est le délai de déclaration ?","a":"<p>La déclaration d'un incident de matériovigilance doit être effectuée <strong>sans délai</strong> (pour un incident grave avéré ou potentiel) par les professionnels de santé :</p><ul><li>Via le <strong>correspondant local de matériovigilance</strong> au sein d'un établissement de santé (hôpital).</li><li><strong>Directement auprès de l'ANSM</strong>, notamment pour les professionnels exerçant en libéral.</li><li>Le signalement s'effectue via le portail unique <strong>signalement-sante.gouv.fr</strong>.</li></ul>"},{"i":"ef5349e3a7d8","n":325,"o":"325-14","u":"Définition","t":"Connaître la déclaration d’un effet indésirable suspecté d’être dû à des biomatériaux","q":"Quel type d'événement relatif aux biomatériaux doit faire l'objet d'une déclaration de matériovigilance ?","a":"<p>Il s'agit de tout incident ou risque d'incident <strong>grave</strong> mettant en cause un dispositif médical (biomatériau) et ayant entraîné ou susceptible d'entraîner :</p><ul><li>Un <strong>décès</strong>.</li><li>Une <strong>dégradation grave de l'état de santé</strong>.</li><li>Une <strong>hospitalisation</strong>.</li><li>Une <strong>intervention</strong>.</li><li>Une <strong>malformation congénitale</strong>.</li><li>Une <strong>menace vitale</strong>.</li></ul>"},{"i":"5ba8ea96d96a","n":325,"o":"325-15","u":"Prise en charge","t":"Identifier une erreur médicamenteuse, ses mécanismes et connaître les conséquences","q":"Quelle est la définition d'une erreur médicamenteuse et ses caractéristiques ?","a":"<p>Une erreur médicamenteuse (EM) est un <strong>événement évitable</strong> par définition, résultant d'un <strong>dysfonctionnement non intentionnel</strong> durant le processus de soins. Elle est habituellement <strong>multifactorielle</strong> (facteurs humains, environnementaux, organisationnels).</p>"},{"i":"c7ac5d74d2eb","n":325,"o":"325-15","u":"Prise en charge","t":"Identifier une erreur médicamenteuse, ses mécanismes et connaître les conséquences","q":"À quelles étapes du circuit de soins une erreur médicamenteuse peut-elle survenir ?","a":"<p>Une erreur médicamenteuse peut survenir à toute étape du circuit du médicament :</p><ul><li><strong>Prescription</strong></li><li><strong>Dispensation</strong></li><li><strong>Administration</strong></li><li><strong>Suivi</strong></li></ul>"},{"i":"c7d8a6f1e512","n":325,"o":"325-15","u":"Prise en charge","t":"Identifier une erreur médicamenteuse, ses mécanismes et connaître les conséquences","q":"Quelles sont les conséquences d'une erreur médicamenteuse et la conduite à tenir en cas de survenue ?","a":"<p>Les conséquences d’une erreur médicamenteuse est d'être à l'origine d'un <strong>risque</strong>, voire d'un <strong>événement indésirable médicamenteux (EIM) avéré</strong>. La conduite à tenir (CAT) face à une erreur médicamenteuse est de :</p><ul><li>La <strong>diagnostiquer</strong></li><li><strong>Traiter les conséquences</strong></li><li><strong>Prévenir la récidive</strong></li><li>La <strong>déclarer au Centre Régional de Pharmacovigilance (CRPV)</strong></li></ul>"},{"i":"ea5182611e59","n":325,"o":"325-15","u":"Prise en charge","t":"Identifier une erreur médicamenteuse, ses mécanismes et connaître les conséquences","q":"Quels sont les deux statuts d'une erreur médicamenteuse ?","a":"<p>Les deux statuts d'une erreur médicamenteuse sont :</p><ul><li><strong>Avérée</strong> : le patient a reçu le mauvais médicament, la mauvaise dose, la mauvaise voie ou le mauvais schéma.</li><li><strong>Potentielle</strong> : l'erreur a été interceptée avant l'administration.</li></ul>"},{"i":"4aeb3ef1bf5f","n":325,"o":"325-16","u":"Définition","t":"Connaître la définition d’une erreur médicamenteuse et de son signalement","q":"Quelle est l'obligation de signalement concernant une erreur médicamenteuse ?","a":"<p>Toute erreur médicamenteuse, qu'elle soit associée ou non à un événement indésirable médicamenteux (EIM), <strong>doit faire l'objet d'une déclaration au CRPV</strong> (Centre Régional de Pharmacovigilance).</p>"},{"i":"dc0ca740a150","n":325,"o":"325-16","u":"Définition","t":"Connaître la définition d’une erreur médicamenteuse et de son signalement","q":"Quel est l'objectif de la \"culture positive de l'erreur\" dans la gestion des erreurs médicamenteuses ?","a":"<p>L'objectif de la \"culture positive de l'erreur\" est de <strong>repérer, transmettre, corriger</strong> les erreurs, en adoptant une <strong>approche systémique et non punitive</strong>, afin de déculpabiliser les acteurs et mieux prévenir les futures erreurs.</p>"},{"i":"f09c69bb67b8","n":325,"o":"325-16","u":"Définition","t":"Connaître la définition d’une erreur médicamenteuse et de son signalement","q":"Quelle est la définition d'une erreur médicamenteuse ?","a":"<p>Une erreur médicamenteuse (EM) est un <strong>écart évitable</strong> entre ce qui aurait dû être fait et ce qui a été réellement fait durant la prise en charge médicamenteuse.</p>"},{"i":"4710ce3e4e8c","n":325,"o":"325-17","u":"Prise en charge","t":"Identifier et prévenir une erreur sur le circuit du médicament","q":"Quels sont les mécanismes clés pour prévenir les erreurs médicamenteuses aux points de transition du patient ?","a":"<p>Aux points de transition du patient (admission, sortie), la <strong>conciliation médicamenteuse</strong> est un mécanisme clé pour éviter les divergences et prévenir les erreurs.</p>"},{"i":"50ddd116dde8","n":325,"o":"325-17","u":"Prise en charge","t":"Identifier et prévenir une erreur sur le circuit du médicament","q":"Quelles mesures spécifiques sont recommandées pour la gestion des médicaments à risque ?","a":"<p>Pour les <strong>médicaments à risque</strong>, un <strong>double contrôle</strong> est recommandé. Ces médicaments incluent notamment les <strong>anticoagulants</strong>, l'<strong>insuline</strong>, les <strong>chimiothérapies</strong> et les <strong>électrolytes concentrés</strong>.</p>"},{"i":"93d7abb2f4e6","n":325,"o":"325-17","u":"Prise en charge","t":"Identifier et prévenir une erreur sur le circuit du médicament","q":"Quelle est la démarche à adopter suite à la survenue ou l'interception d'une erreur médicamenteuse ?","a":"<p>Toute <strong>erreur médicamenteuse</strong> (avérée ou interceptée) doit être déclarée au <strong>CRPV (Centre Régional de Pharmacovigilance)</strong>. L'analyse se fait a posteriori en <strong>RMM (Revue de Morbidité et de Mortalité)</strong>, dans une <strong>démarche systémique et non culpabilisante</strong> visant à identifier la faille du système plutôt que le responsable, suivie d'un plan d'action.</p>"},{"i":"b18ffab2e136","n":325,"o":"325-17","u":"Prise en charge","t":"Identifier et prévenir une erreur sur le circuit du médicament","q":"Comment peut-on sécuriser le circuit du médicament à l'étape d'administration ?","a":"<p>L'étape d'administration du médicament est sécurisée par l'application de la <strong>règle des 5 B</strong> :</p><ul><li><strong>Bon patient</strong></li><li><strong>Bon médicament</strong></li><li><strong>Bonne dose</strong></li><li><strong>Bonne voie</strong></li><li><strong>Bon moment</strong></li></ul>"},{"i":"bcaf51175ff3","n":325,"o":"325-17","u":"Prise en charge","t":"Identifier et prévenir une erreur sur le circuit du médicament","q":"Quelle est la principale mesure technologique pour sécuriser la prescription médicamenteuse ?","a":"<p>La principale mesure technologique est l'<strong>informatisation de la prescription</strong>, qui permet des <strong>alertes interactions médicamenteuses</strong> et améliore la <strong>lisibilité</strong> des ordonnances, réduisant ainsi les risques d'erreurs.</p>"},{"i":"5c65c432fcd9","n":325,"o":"325-2","u":"Définition","t":"Comprendre les enjeux concernant les risques liés aux médicaments et aux biomatériaux","q":"Quelle est l'importance de la iatrogénie médicamenteuse en termes de santé publique et d'économie ?","a":"<ul><li>La iatrogénie médicamenteuse est responsable d'environ <strong>10 % des hospitalisations</strong>.</li><li>Elle est une <strong>cause majeure de morbi-mortalité</strong>.</li><li>Son retentissement économique est lourd, incluant hospitalisations prolongées, et examens complémentaires inutiles et coûteux.</li></ul>"},{"i":"b4aebcb00705","n":325,"o":"325-2","u":"Définition","t":"Comprendre les enjeux concernant les risques liés aux médicaments et aux biomatériaux","q":"Qu'est-ce que la \"cascade médicamenteuse\" et comment survient-elle ?","a":"<p>La \"cascade médicamenteuse\" se produit lorsqu'un <strong>effet indésirable médicamenteux (EIM) n'est pas diagnostiqué</strong> et qu'il conduit à la prescription d'un <strong>médicament supplémentaire</strong> pour traiter ce qui est perçu comme un nouveau symptôme, masquant en réalité l'EIM initial.</p>"},{"i":"c504fd8b2d59","n":325,"o":"325-2","u":"Définition","t":"Comprendre les enjeux concernant les risques liés aux médicaments et aux biomatériaux","q":"Comment s'organise la démarche de gestion des risques liés à l'usage des médicaments et biomatériaux ?","a":"<p>La gestion des risques s'effectue en deux temps :</p><ul><li>Une phase de <strong>veille et d'analyse des risques</strong>.</li><li>Puis la mise en œuvre d'<strong>actions préventives</strong> (visant à supprimer ou diminuer les facteurs de risque) et <strong>correctives</strong> (visant à réduire les conséquences d'un effet indésirable avéré).</li></ul><p>Toute décision doit s'apprécier selon la <strong>balance bénéfices-risques</strong>.</p>"},{"i":"dde2a309e80a","n":325,"o":"325-2","u":"Définition","t":"Comprendre les enjeux concernant les risques liés aux médicaments et aux biomatériaux","q":"Quelle est la nature chimique des médicaments et des biomatériaux, et quelle est l'implication de cette nature concernant leur utilisation ?","a":"<p>Les médicaments et les biomatériaux sont des <strong>xénobiotiques</strong>, c'est-à-dire des substances étrangères à l'organisme. Leur usage induit par nature un <strong>risque d'effet indésirable</strong>.</p>"},{"i":"130acece50bc","n":325,"o":"325-3","u":"Définition","t":"Connaître la définition d’une prescription médicamenteuse inappropriée (PMI)","q":"Quelle est la définition d'une Prescription Médicamenteuse Inappropriée (PMI) ?","a":"<p>Une Prescription Médicamenteuse Inappropriée (PMI) est l'emploi d'un médicament qui engendre <strong>plus de risques que de bénéfices pour le patient</strong>.</p>"},{"i":"6dddad0e2470","n":325,"o":"325-3","u":"Définition","t":"Connaître la définition d’une prescription médicamenteuse inappropriée (PMI)","q":"Quels types de listes validées permettent de repérer les Prescriptions Médicamenteuses Inappropriées (PMI) et dans quels pays sont-elles utilisées ?","a":"<ul><li>Les <strong>critères de Beers</strong> (États-Unis)</li><li>Les <strong>critères STOPP/START</strong> (Europe)</li><li>La <strong>liste de Laroche</strong> (France)</li></ul>"},{"i":"8cb391e913d5","n":325,"o":"325-3","u":"Définition","t":"Connaître la définition d’une prescription médicamenteuse inappropriée (PMI)","q":"Comment définit-on le \"misuse\" dans le cadre d'une Prescription Médicamenteuse Inappropriée (PMI) ?","a":"<p>Le misuse correspond à un <strong>mauvais choix médicamenteux</strong>, à la survenue d'<strong>interactions médicamenteuses cliniquement significatives</strong>, ou à une <strong>posologie/durée de traitement inadaptée</strong>.</p>"},{"i":"b456fa222c91","n":325,"o":"325-3","u":"Définition","t":"Connaître la définition d’une prescription médicamenteuse inappropriée (PMI)","q":"Comment définit-on l'\"overuse\" dans le cadre d'une Prescription Médicamenteuse Inappropriée (PMI) ?","a":"<p>L'overuse correspond à l'utilisation d'un médicament en <strong>l'absence d'indication</strong>, lorsque son <strong>Service Médical Rendu (SMR) est insuffisant</strong>, ou le maintien d'un médicament <strong>devenu inutile</strong> sans réévaluation.</p>"},{"i":"f4239ace4c9d","n":325,"o":"325-3","u":"Définition","t":"Connaître la définition d’une prescription médicamenteuse inappropriée (PMI)","q":"Quelles sont les trois dimensions d'une Prescription Médicamenteuse Inappropriée (PMI) ?","a":"<ul><li>L'<strong>overuse</strong> (excès)</li><li>Le <strong>misuse</strong> (mésusage)</li><li>L'<strong>underuse</strong> (sous-prescription)</li></ul>"},{"i":"fe82c735dce3","n":325,"o":"325-3","u":"Définition","t":"Connaître la définition d’une prescription médicamenteuse inappropriée (PMI)","q":"Comment définit-on l'\"underuse\" dans le cadre d'une Prescription Médicamenteuse Inappropriée (PMI) ?","a":"<p>L'underuse désigne l'<strong>absence de prescription d'un médicament</strong> dont le patient pourrait tirer un bénéfice clair, par exemple l'absence d'anticoagulation chez un patient avec une fibrillation atriale à risque.</p>"},{"i":"10638d066793","n":325,"o":"325-7","u":"Définition","t":"Connaître les caractéristiques des EIM chez les personnes âgées","q":"Quelles sont les principales mesures de prévention des effets indésirables médicamenteux (EIM) chez la personne âgée ?","a":"<ul><li><strong>Hiérarchiser les objectifs</strong> de traitement.</li><li><strong>Limiter la polymédication</strong> et <strong>déprescrire</strong> les médicaments inutiles.</li><li><strong>Adapter la posologie</strong> des médicaments au débit de filtration glomérulaire (DFG) estimé (notamment via la formule de <strong>Cockcroft</strong>).</li><li><strong>Éviter les médicaments inappropriés</strong> (ex: <strong>sédatifs, anticholinergiques, antihypertenseurs centraux</strong>).</li><li>Privilégier les <strong>médicaments anciens</strong> et bien évalués.</li></ul>"},{"i":"31184cc0361f","n":325,"o":"325-7","u":"Définition","t":"Connaître les caractéristiques des EIM chez les personnes âgées","q":"Quelle est la présentation clinique atypique ou frustre fréquente des effets indésirables médicamenteux (EIM) chez la personne âgée ?","a":"<p>Les EIM peuvent se présenter de manière atypique ou frustre, se manifestant par une <strong>chute</strong>, une <strong>confusion</strong> ou une <strong>hypotension orthostatique</strong>.</p>"},{"i":"41ff64091df1","n":325,"o":"325-7","u":"Définition","t":"Connaître les caractéristiques des EIM chez les personnes âgées","q":"Quels sont les mécanismes pharmacocinétiques et pharmacodynamiques qui expliquent le sur-risque d'effets indésirables médicamenteux (EIM) chez la personne âgée ?","a":"<ul><li><strong>Modifications pharmacocinétiques</strong> :<ul><li>Diminution du débit de filtration glomérulaire (DFG) entraînant une accumulation des médicaments à élimination rénale (ex: <strong>aminosides, lithium</strong>).</li><li>Hypoalbuminémie (due à la dénutrition) augmentant la fraction libre de certains médicaments (ex: <strong>AVK, sulfamides</strong>).</li><li>Diminution du volume de distribution en cas de déshydratation.</li><li>Diminution du métabolisme hépatique.</li></ul></li><li><strong>Modifications pharmacodynamiques</strong> :<ul><li>Sensibilité accrue du système nerveux central (SNC).</li><li>Fragilité homéostatique.</li></ul></li></ul>"},{"i":"69de7a74df31","n":325,"o":"325-7","u":"Définition","t":"Connaître les caractéristiques des EIM chez les personnes âgées","q":"Comment définit-on une personne \"âgée\" dans le contexte des effets indésirables médicamenteux (EIM) ?","a":"<p>Une personne est définie comme \"âgée\" dans ce contexte si elle est âgée de <strong>≥ 75 ans</strong>, ou de <strong>≥ 65 ans et polypathologique</strong>.</p>"},{"i":"5c3c732f1c87","n":325,"o":"325-8","u":"Définition","t":"Connaître les objectifs et principes de la pharmacovigilance","q":"Quelles sont les 5 étapes de la pharmacovigilance ?","a":"<ul><li><strong>Détection</strong> (signal d'EIM)</li><li><strong>Évaluation</strong> (quantification du risque)</li><li><strong>Compréhension</strong> (mécanisme, facteurs favorisants)</li><li><strong>Prévention</strong></li><li><strong>Gestion du risque</strong></li></ul>"},{"i":"ab350309a978","n":325,"o":"325-8","u":"Définition","t":"Connaître les objectifs et principes de la pharmacovigilance","q":"Comment s'organise la pharmacovigilance en France et en Europe ?","a":"<ul><li><strong>Échelon Régional</strong> : les <strong>CRPV</strong> (Centres Régionaux de Pharmacovigilance) sont chargés du recueil, de la validation et de l'évaluation des EIM, de l'aide au diagnostic, de l'imputabilité, du conseil et de la formation.</li><li><strong>Échelon National</strong> : l'<strong>ANSM</strong> (Agence Nationale de Sécurité du Médicament et des produits de santé) coordonne le système et prend les décisions (restriction, contre-indication, retrait, plan de gestion des risques).</li><li><strong>Échelon Européen</strong> : l'<strong>EMA</strong> (Agence Européenne des Médicaments) et le <strong>PRAC</strong> (Comité pour l'évaluation des risques en pharmacovigilance) centralisent les décisions à l'échelle de l'UE.</li></ul>"},{"i":"c56989b98432","n":325,"o":"325-8","u":"Définition","t":"Connaître les objectifs et principes de la pharmacovigilance","q":"Quel est le principal moyen de détection des effets indésirables rares ou retardés en pharmacovigilance ?","a":"<p>La pharmacovigilance repose principalement sur la <strong>notification spontanée</strong> des effets indésirables, seul moyen efficace de détecter les EIM rares ou retardés qui n'auraient pas été mis en évidence avant l'Autorisation de Mise sur le Marché (AMM).</p>"},{"i":"d73e9ee68ac2","n":325,"o":"325-8","u":"Définition","t":"Connaître les objectifs et principes de la pharmacovigilance","q":"Quelle est la définition de la pharmacovigilance ?","a":"<p>La pharmacovigilance (PV) désigne la <strong>surveillance des médicaments après leur commercialisation</strong> (post-AMM), la <strong>prévention</strong> et la <strong>gestion du risque d'effets indésirables des médicaments (EIM)</strong>.</p>"}]};